CREATE TEMP TABLE acceptance_destinations AS SELECT id,kind FROM plugin_data.csf_sheet_sync_destinations WHERE id IN ((SELECT (value->>'id')::uuid FROM sync_fixture WHERE name='destination'),'eac00000-0000-4000-8000-000000000001','eaf20000-0000-4000-8000-000000000001');
UPDATE plugin_data.csf_sheet_sync_destinations SET enabled=true,comment_capability='available',privacy_verified_at=now(),last_synced_at=now() WHERE id IN (SELECT id FROM acceptance_destinations);
UPDATE plugin_data.csf_sheet_writeback_ledger SET status='superseded' WHERE destination_id IN (SELECT id FROM acceptance_destinations) AND status IN ('pending_export','retry_export','exporting','unknown_outcome');
UPDATE plugin_data.csf_sheet_sync_changes SET status='discarded' WHERE destination_id IN (SELECT id FROM acceptance_destinations) AND status='pending';
DO $$ DECLARE b record; snapshot jsonb; BEGIN FOR b IN SELECT * FROM plugin_data.csf_sheet_sync_bindings WHERE destination_id IN (SELECT id FROM acceptance_destinations) LOOP snapshot:=plugin_data.csf_sheet_sync_destination_snapshot(b.organization_id,b.destination_id,b.record_kind,b.record_id); IF snapshot IS NOT NULL THEN INSERT INTO plugin_data.csf_sheet_writeback_ledger(organization_id,spreadsheet_file_id,destination_id,record_kind,record_id,source_version,payload,status) SELECT b.organization_id,d.spreadsheet_file_id,b.destination_id,b.record_kind,b.record_id,md5(snapshot::text),snapshot,'exported' FROM plugin_data.csf_sheet_sync_destinations d WHERE d.id=b.destination_id ON CONFLICT(destination_id,record_kind,record_id,source_version) WHERE destination_id IS NOT NULL DO UPDATE SET status='exported'; UPDATE plugin_data.csf_sheet_sync_bindings SET last_export_version=md5(snapshot::text) WHERE id=b.id; END IF; END LOOP; END $$;
INSERT INTO plugin_data.csf_sheet_sync_changes(organization_id,destination_id,record_kind,record_id,source_version,remote_version,payload,status,reviewed_by)
SELECT 'ea100000-0000-4000-8000-000000000001',d.id,CASE WHEN d.kind='applications' THEN 'application' ELSE 'point_submission' END,CASE WHEN d.kind='applications' THEN 'ea600000-0000-4000-8000-000000000001'::uuid ELSE 'ead00000-0000-4000-8000-000000000001'::uuid END,'fixture-version','acceptance-'||action,jsonb_build_object('action',action),'accepted','ea000000-0000-4000-8000-000000000001' FROM acceptance_destinations d CROSS JOIN unnest(ARRAY['approved','rejected','needs_action']) action WHERE d.kind<>'class';
INSERT INTO plugin_data.csf_sheet_sync_comments(organization_id,destination_id,binding_id,provider_thread_id,provider_message_id,provider_version,author,body,resolved)
SELECT b.organization_id,b.destination_id,b.id,'acceptance-thread',post,'v1','{}','Fictional acceptance discussion',true FROM plugin_data.csf_sheet_sync_bindings b CROSS JOIN unnest(ARRAY['acceptance-root','acceptance-reply']) post WHERE b.id=(SELECT (value->>'id')::uuid FROM sync_fixture WHERE name='binding');
UPDATE plugin_data.csf_sheet_sync_bindings SET thread_bindings=thread_bindings||jsonb_build_object('eafe0000-0000-4000-8000-000000000002',jsonb_build_object('threadId','acceptance-thread','postId','acceptance-root','localVersion','fixture-version')) WHERE id=(SELECT (value->>'id')::uuid FROM sync_fixture WHERE name='binding');
CREATE TEMP TABLE acceptance_evidence AS SELECT jsonb_build_object('export_ids',(SELECT jsonb_agg(id) FROM plugin_data.csf_sheet_writeback_ledger WHERE destination_id IN (SELECT id FROM acceptance_destinations) AND status='exported'),'change_ids',(SELECT jsonb_agg(id) FROM plugin_data.csf_sheet_sync_changes WHERE remote_version LIKE 'acceptance-%'),'comment_ids',(SELECT jsonb_agg(id) FROM plugin_data.csf_sheet_sync_comments WHERE provider_thread_id='acceptance-thread'),'native_receipts',jsonb_build_array(jsonb_build_object('binding_id',(SELECT value->>'id' FROM sync_fixture WHERE name='binding'),'local_message_id','eafe0000-0000-4000-8000-000000000002','thread_id','acceptance-thread','post_id','acceptance-root','local_version','fixture-version')),'provider_versions',(SELECT jsonb_object_agg(id::text,'fixture-drive-version') FROM acceptance_destinations),'observations','Fictional complete copied workbook journey with reviewed decisions and native replies.') evidence;
SELECT extensions.throws_ok($$SELECT plugin_data.csf_record_sheet_sync_acceptance('ea100000-0000-4000-8000-000000000002','ea000000-0000-4000-8000-000000000001','ea700000-0000-4000-8000-000000000002',(SELECT array_agg(id) FROM acceptance_destinations),(SELECT evidence||'{"change_ids":[]}'::jsonb FROM acceptance_evidence),'Incomplete journey')$$,'P0001','The copied-workbook journey is incomplete.','empty decision evidence cannot authorize live sync');
